INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Arthur Morgan', 'Human', 'Arthur Morgan is a central character and the main protagonist of Red Dead Redemption 2. Arthur Morgan was born circa 1863 to Beatrice and Lyle Morgan, somewhere in the northern United States. Around 1877, Arthur was found and picked up of the streets by Dutch van der Linde and Hosea Matthews.' FROM characters WHERE igdb_id = 12330 ON CONFLICT (character_id, language_code) DO NOTHING;
