INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Pikachu', 'Other — Unknown', 'The mascot species of the Pokémon franchise, Pikachu is an Electric-type rodent that evolves from Pichu and can later evolve into Raichu. Pikachu has been extensively featured in nearly every piece of Pokémon media, and its popularity extends outside of its home series - it has been playable in every Super Smash Bros. game, painted on commercial airliners, and has its own balloon in the Macy''s Thanksgiving Day Parade.' FROM characters WHERE igdb_id = 4907 ON CONFLICT (character_id, language_code) DO NOTHING;
