INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Walton Simons', 'Human', 'His past is not known but he is known to the public as an important government official and the Director of FEMA. He was appointed to FEMA through Page''s manipulation of an unnamed senator infected with the Gray Death, and went to work immediately. A cloak-and-dagger man, Simons was the first higher-up on the scene after JC Denton''s capture of NSF operatives in Battery Park; his interrogation ended with Simons personally executing both prisoners.' FROM characters WHERE igdb_id = 2629 ON CONFLICT (character_id, language_code) DO NOTHING;
