INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('commander-shepard-male', 10, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lnozdao4v2rzjbpvatfx.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Commander Shepard (male)', 'Human', 'Commander Shepard is the player character in BioWare''s Mass Effect game trilogy: Mass Effect, Mass Effect 2, and Mass Effect 3. A veteran soldier of the Systems Alliance Navy military and N7-graduate of the Interplanetary Combatives Training (ICT) program, and the first human Citadel Council Spectre, Shepard works to stop "the Reapers", a sentient synthetic-machine race dedicated to wiping out all organic life.
INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 10 AND g.igdb_id = 73 ON CONFLICT DO NOTHING;
INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, false FROM characters c, games g WHERE c.igdb_id = 10 AND g.igdb_id = 74 ON CONFLICT DO NOTHING;
INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('garrus-vakarian', 9, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tdfgjxuzv06nzdd99h6l.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 2)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Garrus Vakarian', 'Alien', 'Garrus Vakarian is a turian, formerly part of C-Sec''s Investigation Division. Like most turians, Garrus had his military training at fifteen, but later followed in his father''s footsteps to become a C-Sec officer. He was responsible for the investigation of Saren Arterius, the Council''s top Spectre, after the Alliance claimed Saren had gone rogue. Although Garrus was told that the investigation was over, he decided to defy the Executor''s order and pursue another lead on his own. Eventually, Garrus attempts to join Commander Shepard''s team to help defeat Saren and the geth.' FROM characters WHERE igdb_id = 9 ON CONFLICT (character_id, language_code) DO NOTHING;
INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 9 AND g.igdb_id = 73 ON CONFLICT DO NOTHING;
INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, false FROM characters c, games g WHERE c.igdb_id = 9 AND g.igdb_id = 74 ON CONFLICT DO NOTHING;
