INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Felicia', 'Female — Animal', 'Felicia was first introduced in Darkstalkers: The Night Warriors as one of two female characters alongside Morrigan Aensland. She has appeared in every game in the series and in numerous cross overs including Marvel vs. Capcom 2: New Age of Heroes along with Morrigan, Baby Bonnie Hood and Anakaris. 
