INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('the-hammer', 2057, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nvlthded6tp5weqs43ef.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 5)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'The Hammer', 'Unknown', 'The Hammer of Sauron was a stretcher bearer during the War of the Last Alliance, who grew disillusioned and became seduced by Sauron''s power after he came upon the Dark Lord''s mace which had been dropped after Isildur defeated him. After that the Hammer realized that his life in helping wounded soldiers looking to find glory in war was wasted and thought that if they were so desperate to find glory on the battlefield then he would be more than happy to give it to them. 
