INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('garrett', 4875, 'https://images.igdb.com/igdb/image/upload/t_cover_big/c4j0cb96bgakr88bjfvl.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Garrett', 'Human', 'The protagonist of the Thief games is called Garrett, a master thief with a cynical view who wishes nothing more than to be left alone. He unwittingly becomes involved in a series of dramatic events, even though he just want to steal in peace. Growing up without any parents, he spent his childhood on the streets, having to pickpocket from people with money in order to survive. Later on a secret organization called The Keepers (dedicated to observe and maintain stability in the city) decided to recruit him. Garrett was given training in the arts of stealth, but soon found that it was way more profitable to make use of these skills as a thief than to continue working as an agent.
