INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Lithariel', 'Female — Unknown', 'Lithariel is the daughter of Lady Marwen, Queen of the Shore. As an infant, she was the only survivor of a trading ship which fell prey to the raids of the Tribesmen. Queen Marwen adopted the infant as a daughter and she is now the first in line for the throne. 
