INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Abe', 'Alien', 'Abe is the central character in the Oddworld video game series, created by Oddworld Inhabitants. He first appeared in the 1997 game "Oddworld: Abe''s Oddysee." Abe is a Mudokon, a species native to the planet Oddworld. He starts as a lowly floor waxer at RuptureFarms, the largest meat-processing plant on Oddworld, run by the ruthless Glukkons. The Mudokons are enslaved by the Glukkons and forced to work in dangerous and oppressive conditions.
