INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'G-Man', 'Unknown', 'The G-Man is a mysterious and enigmatic character encountered several times in the Half-Life series. Referred to as a "sinister interdimensional bureaucrat",[3] he is known to display peculiar behavior and to wield powers far beyond those of a human. His identity and motives remain completely unexplained. His allegiance also remains unknown to this day. INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 136 AND g.igdb_id = 233 ON CONFLICT DO NOTHING;
