INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('delilah', 7155, 'https://images.igdb.com/igdb/image/upload/t_cover_big/eur3nfimk280attdbtdq.jpg', '#0f172a', (SELECT id FROM genders WHERE igdb_id = 1), (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Delilah', 'Female — Human', 'Delilah is the deuteragonist of Firewatch and the supervisor of Henry, the game''s protagonist. Henry remains in nearly constant contact with her via radio and can be reached at any time she or Henry starts a conversation or Henry finds something worth of reporting to her, except during sections taking place in the cave. As the game progresses, increasing doubt is shed on Delilah, her relationship with Henry, her affiliation and what she potentially knows. As such, the player has the choice when making discoveries to report to her or not. The player never meets Delilah in person, leaving her appearance a mystery.' FROM characters WHERE igdb_id = 7155 ON CONFLICT (character_id, language_code) DO NOTHING;
