INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('kenny', 3472, 'https://images.igdb.com/igdb/image/upload/t_cover_big/vsljodd573c7kdcwr8wu.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Kenny', 'Human', 'In Telltale Games'' The Walking Dead, there''s many main characters and one of them is Kenny. As a kid he was raised by his father, who taught him how to repair broken cars. That knowledge soon extended to boats due to his love of the water and traveling. As an adult, Kenny became a commercial fisherman, hunting for the snapper fish and yellow fin. During a fishing trip, he found a sick octopus and decided to bring it to a veterinarian''s office. There he met and fell in love with Katjaa. They got married and later had a son called Kenny Jr, also nicknamed Duck. The family were returning from Memphis, Tennessee after visiting Katjaa''s sister when the outbreak started.
