INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('booker-dewitt', 1043, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cm2zg.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Booker DeWitt', 'Human', 'Booker DeWitt (Troy Baker), the player protagonist, is a disgraced former agent of the Pinkerton National Detective Agency. As a soldier in the 7th Cavalry Regiment, he had performed brutal acts against native American Indians at the Battle of Wounded Knee to defend his own honor; these acts left him emotionally scarred, leading to excessive drinking and gambling and earned him the title "White Injun" due to his tendency to scalp those he killed. He was given an opportunity to be baptised and start anew, but ultimately declined. He was subsequently dismissed for behavior beyond the acceptable bounds of the Agency,[2] but considers his actions with the Pinkertons in quelling labour strikes to be among his many sins. He continues to work as a private investigator from New York City, referring to himself as an "independent contractor". Outwardly, he cares little for the extraordinary, provided that it does not interfere with his ability to do his job; internally, he is disturbed by both his role in the events at Wounded Knee and recurring visions of New York City under attack from the air. Booker is skeptical of faith, unwilling to accept the idea that he can be absolved of his sins by embracing religion, as he considers his sins to be so extreme as to demand a penance rather than forgiveness.' FROM characters WHERE igdb_id = 1043 ON CONFLICT (character_id, language_code) DO NOTHING;
