INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('the-skeleton-king', 9205, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lngvaibuwwfg5yx2buzj.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'The Skeleton King', 'Human', 'The Skeleton King is a boss character found in Diablo 3, formerly known as King Leoric. Even though he was born in Kehjistan, Leoric decided to take his family and travel into the lands of Khanduras, where he in the name of the Zakarum, declared himself as the king. At first, the people of Khanduras disliked the idea to have him as a ruler. However, as time passed, they grew to like and respect him, thanks to his purity of heart and deed.
INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('rigby', 8950, 'https://images.igdb.com/igdb/image/upload/t_cover_big/lwfpzfgb4ebsvy6ivvxz.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 3)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Rigby', 'Animal', 'Rigby is one of the protagonists of Carton Networks'' Regular Show, as well as a playable character in the online game Fusion Fall. He''s a 23 year old brown raccoon with short, spiky hair and made his debut in the pilot episode, working in the park as a groundskeeper. Rigby received the nickname "The One Cheek Wonder", after a friend damaged his butt in a "fun" fight. The raccoon had to get surgery that resulted in his behind looking like it only had one butt cheek.
