INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('tommy-vercetti', 218, 'https://images.igdb.com/igdb/image/upload/t_cover_big/pp7sg2zylytachmzyqky.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Tommy Vercetti', 'Human', 'Tommy, an Italian-American, is portrayed with a tall, swarthy, handsome appearance, combed dark brown, almost black hair, and a constant five o''clock shadow. He first appears wearing a light blue-green Hawaiian shirt with dark blue palm trees printed on it, a gold pearl necklace around his neck, a gold watch around his left wrist, and a pair of blue jeans and white sneakers. This outfit becomes known as Tommy’s "street" clothes. As the game progresses, Tommy is offered more wardrobe options: he obtains a blue-purple pastel suit with the sleeves rolled up over a black dress shirt and black loafers, as well as the option of a dark pinstripe suit labeled as "Mr. Vercetti" (which bears similarities to Tony Montana''s uniform). A light green costume is available to perform a bank robbery, complete with a hockey mask, and is even able to wear the uniform for an allied gang, among many others.
