INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('sejuani', 9219, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nroy9ceyha6zrzxwvpgv.jpg', '#0f172a', (SELECT id FROM genders WHERE igdb_id = 1), (SELECT id FROM species WHERE igdb_id = 5)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Sejuani', 'Female — Unknown', 'Sejuani is a playable character in League of Legends. As a child, the leader of the Winter''s Claw watched her tribe die, one after one. She was the only one of her siblings that survived to become ten years old. Yet she feared for her life, sure that she would be the next to die. Becoming desperate, she sought spiritual counsel from the tribe''s mystic. She told Sejuani that she one day would conquer and unite the tribes of the Freljord. However, the mystic left out the event of her death.
INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('kurisu-makise', 5498, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p4cpr8ca6qtvijqnoith.jpg', '#0f172a', (SELECT id FROM genders WHERE igdb_id = 1), (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Kurisu Makise', 'Female — Human', 'Kurisu Makise is a genius girl who graduated from university at the age of seventeen. She is a research member in Victor Qondria University''s Brain Research Program and her research on the brain''s memory retention system has earned critical acclaim in the scientific community. She later joins the Future Gadget Lab as Member 004 after a series of encounters with Rintaro Okabe, where she helps to create the Time Leap Machine, a microwave oven capable of sending memories 48 hours back in time. She has a myriad of nicknames, most of which are invented by Rintaro, much to her dismay.' FROM characters WHERE igdb_id = 5498 ON CONFLICT (character_id, language_code) DO NOTHING;
