INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Suzuha Amane', 'Female — Human', 'Suzuha Amane (阿万音鈴羽) is a part-time employee for Yugo Tennoji, the landlord of Rintaro''s flat and is on a search for her father in Akihabara. She enjoys riding her bicycle and appears to be at odds with Kurisu. She is the eight and last member of the Future Gadget Laboratory.' FROM characters WHERE igdb_id = 5500 ON CONFLICT (character_id, language_code) DO NOTHING;
