INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('funtime-freddy', 10236, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cm376.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 4)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Funtime Freddy', 'Android', 'Funtime Freddy is a major antagonist who first appeared in Five Nights at Freddy''s: Sister Location as the titular, secondary antagonist. He is a circus-themed version of Freddy Fazbear. He is also one of the entertainers from the Funtime Auditorium, which is located from the east of Circus Baby''s Entertainment and Rental (although he isn''t seen in the said auditorium).' FROM characters WHERE igdb_id = 10236 ON CONFLICT (character_id, language_code) DO NOTHING;
