INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Luka Urushibara', 'Human', 'Luka Urushibara (漆原るか) is a close friend of Mayuri Shiina and so-called protégé of Rintaro Okabe. While feminine in appearance and personality, Luka is a male. Mayuri is his classmate, who often attempts to coerce him into cosplaying (without much success).' FROM characters WHERE igdb_id = 5501 ON CONFLICT (character_id, language_code) DO NOTHING;
