INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Faris Nyannyan', 'Female — Unknown', 'Faris NyanNyan (フェイリス・ニャンニャン), real name Rumiho Akiha (秋葉 留美穂), is a part-time employee and owner of the maid cafe May Queen Nyan-nyan, the same maid cafe that Mayuri works at, and is the most popular waitress there. She is a second year student in Kanaria Private Academy and is Yukitaka Akiha''s daughter.' FROM characters WHERE igdb_id = 5502 ON CONFLICT (character_id, language_code) DO NOTHING;
