INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Yugo Tennoji', 'Human', 'Yugo Tennouji (天王寺 裕吾) is Rintaro Okabe''s landlord and the owner of the CRT store. He has a great passion for CRT Television and refuses to upgrade to any other type. This coupled with the fact he owns a CRT store has resulted in Rintaro nicknaming him "Mr. Braun" after the inventor of CRTs, German physicist Ferdinand Braun and the common Japanese name for CRTs, "Braun Tubes". His daughter Nae is his top priority and he will go to desperate lengths to ensure her safety.' FROM characters WHERE igdb_id = 5505 ON CONFLICT (character_id, language_code) DO NOTHING;
