INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('takumi', 9695, 'https://images.igdb.com/igdb/image/upload/t_cover_big/we466tbbyhg7s8b4mvxe.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 5)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Takumi', 'Unknown', 'Takumi, a very talented archer, is a major playable character from Fire Emblem Fates. He is the third child of four in the Hoshidan royal family. Takumi has been perfecting his practice of martial arts in order to have people recognize him for his strength. Starting out with a sword, he was actually pretty good. Sadly he was humiliatingly crushed by Ryoma during a match  that caused him to become an archer instead. 
