INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('francis-york-morgan', 9706, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gnywmcua6bpyarqpcpjt.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Francis York Morgan', 'Human', 'Francis York Morgan is an FBI special agent, and the main character of Swery65''s game, Deadly Premonition. Even though he solves cases in a very peculiar way, he''s a very competent agent with a real talent for criminal profiling. His personality differs from normal humans with his odd mannerisms and weird morning routines (like drinking his strong morning coffee and seeing secret messages in each cup). Francis York Morgan also urges people to call him York, because that''s what "everyone does".
