INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Dr. Zed', 'Female — Human', 'Dr. Zed is the only human resident in Fyrestone to meet the Vault Hunters upon their arrival in Pandora. Dr. Zed lost his medical license for unknown reasons, probably something to do with the fact that he never had any medical training. Currently, he maintains the medical vendors around Pandora, more or less. He spends much of his time in the infirmary chopping up corpses.' FROM characters WHERE igdb_id = 3715 ON CONFLICT (character_id, language_code) DO NOTHING;
