INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('mario', 3726, 'https://images.igdb.com/igdb/image/upload/t_cover_big/iurhmhenrrsdnsc4zbva.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Mario', 'Human', 'A Plumber who saves the princess and defeats Bowser, his first appearance was in the 1981 game "Donkey Kong" as he is trying to save Pauline from the evil Donkey Kong, since the game grew in popularity, so did the plumber, until he got his own game in 1983. "Mario Bros." is a game where Mario and Luigi defeat creatures in the sewer, the game got positive reception, but Mario Bros. wasn''t the game to improve Mario''s popularity, and the game did not sell well in North America due to the Video Game Crash of 1983. Soon, Nintendo made what is known as one of the most iconic games of all time, "Super Mario Bros." , where Mario has to save Princess Toadstool from King Koopa. The game was a massive hit on the NES, selling about 40 million copies. They soon made more Mario games and now Mario is not only one of the best selling franchises but also one the most iconic video game characters ever.' FROM characters WHERE igdb_id = 3726 ON CONFLICT (character_id, language_code) DO NOTHING;
