INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('spider-man', 5743, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nccoer1nqjxrlemlpbyx.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Spider-Man', 'Human', 'Spider-Man, also known as Peter Parker, is a superhero created by Marvel Comics. After being bitten by a radioactive spider, Peter gains superhuman abilities such as wall-crawling, enhanced strength, and agility. Balancing his life as a high school student and later as a photographer, he fights crime in New York City, driven by the mantra, "With great power comes great responsibility," taught to him by his Uncle Ben.' FROM characters WHERE igdb_id = 5743 ON CONFLICT (character_id, language_code) DO NOTHING;
