INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Tiatha ir-Adech', 'Female — Unknown', 'Powerful and well connected Leshin. Looking for her son, Folren, who is believed to have died during the war. Convinced he is either still alive or buried improperly, she hires Sofya to find out what really happened to him, but may have alternate motives for the investigation.' FROM characters WHERE igdb_id = 9784 ON CONFLICT (character_id, language_code) DO NOTHING;
