INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Master Chief', 'Human', 'John-117 "Master Chief" is a fictional character and the main protagonist of the Halo fictional universe, created by Bungie. Master Chief is a player character in the series of science fiction first-person shooter video games: Halo: Combat Evolved, Halo 2, Halo 3, and Halo 4. Outside of video games, the character appears in novels – Halo: The Fall of Reach, Halo: The Flood, Halo: First Strike, and Halo: Uprising – and has cameos in other Halo media, including Halo: Reach, Halo: Ghosts of Onyx, The Halo Graphic Novel, Halo Legends and Halo 4: Forward Unto Dawn.INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 2800 AND g.igdb_id = 991 ON CONFLICT DO NOTHING;
