INSERT INTO characters (slug, igdb_id, main_image, background_color, gender_id, species_id) VALUES ('big-boss', 5389, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cm363.jpg', '#0f172a', NULL, (SELECT id FROM species WHERE igdb_id = 1)) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO character_translations (character_id, language_code, name, role, description) SELECT id, 'en', 'Big Boss', 'Human', 'Is a renowned special forces operative and mercenary commander. He founded U.S. Army Special Forces Unit FOXHOUND, along with the mercenary company Militaires Sans Frontières, and was one of the founding members of the Patriots. Big Boss later established the military states of Outer Heaven and Zanzibar Land as bases for his companies, in order to realize his ambitions of creating a nation for soldiers. Considered by some as "The Greatest Warrior of the 20th Century," he earned such monikers as "the Legendary Soldier" and "the Legendary Mercenary," feared in combat by both friend and foe as a hero and a madman.' FROM characters WHERE igdb_id = 5389 ON CONFLICT (character_id, language_code) DO NOTHING;
INSERT INTO character_games (character_id, game_id, is_primary) SELECT c.id, g.id, true FROM characters c, games g WHERE c.igdb_id = 5389 AND g.igdb_id = 380 ON CONFLICT DO NOTHING;
